        C = rho.*mu/b.*(R1p.*rho./beta1-1).*I12;

        %Maximum of U
        [Umax,imax] = max(U);
        rhomaxU = rho(imax);
        
        %Maximum of U12
        [U12max,i12max] = max(U12);
        rhomaxU12 = rho(i12max);
        
        %Maximum of U1 (here, strat 2)
        [U1max,i1max] = max(U1);
        rho1maxs2 = rho(i1max);
        
        %Maximum of U1 (here, strat 1)
        %[U1s1max,i1s1max] = max(U1s1);
        %rho1maxs1 = rho(i1s1max);              
        
        %Maximum of U2 (here, strat 2)
        [U2max,i2max] = max(U2);
        rho2maxs2 = rho(i2max);
        
        %C : a and b
        [minC,iminC] = min(C.*(rho<alpha1));
        aC=rho(iminC);
        [maxC,imaxC] = max(C);
        bC=rho(imaxC);
        
        rho2max = alpha2/2;
        rho1maxs1 = beta1/R1*(sqrt(R1)-1); %strategy 1
        
        %on stocke les resultats dans un tableau
        tab = [tab; beta1,beta2,gamma1,gamma2,mu,R1,R2,...
            rho1maxs1,rho1maxs2,rho2maxs2,rhomaxU12,alpha1,alpha2];
        
        %cond=rho1maxs1<rhomaxU12;
        %cond=round(rho1maxs1,3)>=round(aC,3);
        %cond = (rhomaxU >= rho1maxs1 & rhomaxU <=rho2maxs2);
        
        % Representation graphique    
        if (cond)
            
            figure(1)
            plot(rho,P1,rho,P2,rho,P12)
            legend('\Pi_1','\Pi_2','\Pi_{12}')
            title([{'Prevalence of the SIRxSIS model (strategy 2)'},...
            {['\beta_1=',num2str(beta1), ' \beta_2=',num2str(beta2),' \gamma_1=',num2str(gamma1),' \gamma_2=',...
            num2str(gamma2), ' s1=', num2str(s1),' s2=', num2str(s2), '\mu=', num2str(mu), ' \pi=',  num2str(b),...
            ' R_1(0)=' num2str(round(R1,2)), ' R_2(0)=' num2str(round(R2,2)), ' \rho_1=' num2str(round(alpha1,2)),...
            ' \rho_2=' num2str(round(alpha2,2)),]}])
            xlabel("\rho","fontweight","bold")
            ylabel("\Pi(\rho)","fontweight","bold")


            figure(2)
            %plot(rho,U1,rho,U2, rho, U12,rho,U,rho,U1s1,rho,C)
            plot(rho,U1,rho,U2, rho, U12,rho,U)
            %legend('U_1^{s_2}','U_2','U_{12}','U','U_1^{s_1}','C')
            legend('U_1','U_2','U_{12}','U')

            title([{'Utility of the SIRxSIS model (strategy 2)'},...
            {['$\beta_1$=',num2str(beta1), ' $\beta_2=$',num2str(beta2),' $\gamma_1(0)=$',num2str(round(gamma1,2)),' $\gamma_2(0)=$',...
            num2str(round(gamma2,2)), ' $s_1=$', num2str(s1),' $s_2=$', num2str(s2), '$\mu=$', num2str(mu), ' $\pi=$',  num2str(b),...
            ' $\mathtt R_1(0)=$' num2str(round(R1,2)), ' $\mathtt R_2(0)=$' num2str(round(R2,2))]},...
            {[' $\rho_1\prime=$' num2str(round(alpha1,2)),' $\rho_2\prime=$' num2str(round(alpha2,2)),...
            ' $\hat \rho=$' num2str(round(rhomaxU,2)),' $\hat \rho_{12}=$' num2str(round(rhomaxU12,2)),' $\hat\rho_1^{\rm s_1}=$',num2str(round(rho1maxs1,2)),...
            ' $\hat\rho_1^{\rm s_2}=$',num2str(round(rho1maxs2,2)),' $\hat\rho_2=$',num2str(round(rho2max,2)),...
            ' $a=$', num2str(round(aC,2)),' $b=$', num2str(round(bC,2))]}],...
            'Interpreter','latex')
            xlabel("\rho","fontweight","bold")
            ylabel("U(\rho)","fontweight","bold")

            rho1maxs1
            rho1maxs2;
            rho2max
            rho2maxs2;
            rhomaxU12;
            rhomaxU
        end
end
end

