maxRho1 = beta1/(R10*s1)*(sqrt(R10*mu/(mu-beta1*c))-1);
maxRho2 = beta2/(2*s2)*(1-1/R20+c);

for rho=vecRho
    [S,I1,I2,I12,IR2,R1] = ES_SIRSIS_V4(b,beta1,beta2,s1,s2,rho,gamma1,gamma2,mu);
    
    R2p = beta2/(gamma2+s2*rho+mu);

    P2 = 1-1/R2p;
    P1 = mu/b*(I1+I12);
    P = (1-1/R2p + mu/b*I1)*(rho<minAlpha) + P2*(rho>=alpha1 & rho<alpha2) + P1*(rho>=alpha2 & rho<alpha1) ;
    
    vecU = [vecU,rho.*(P+c)];
end

figure(1)
plot(vecRho,max(vecU,0))
xlim([0,vecRho(end)])
[maxU,imaxU] = max(vecU);
rhomaxU = vecRho(imaxU);
[maxU12,imaxU12] = max(vecU.*(vecRho<minAlpha));
rhomaxU12 = vecRho(imaxU12);

title([{'Utility of the SIRxSIS model (strategy 2)'},...
            {['$\beta_1$=',num2str(beta1), ' $\beta_2$=',num2str(beta2),' $\gamma_1(0)$=',num2str(round(gamma1,2)),' $\gamma_2(0)$=',...
            num2str(round(gamma2,2)), ' $s_1$=', num2str(s1),' $s_2$=', num2str(s2), ' $\mu$=', num2str(mu), ' $\pi$=',  num2str(b),...
            ' $\mathtt R_1(0)$=' num2str(round(R10,2)), ' $\mathtt R_2(0)=$' num2str(round(R20,2))]},...
            {[' $\rho_1\prime$=' num2str(round(alpha1,2)),' $\rho_2\prime$=' num2str(round(alpha2,2)),...
            ' $\hat \rho$=' num2str(round(rhomaxU,2)),' $\hat \rho_{12}$=' num2str(round(rhomaxU12,2)),...
            ' $\hat \rho_{1}^{SIR}$=' num2str(round(maxRho1,2)),' $\hat \rho_{2}$=' num2str(round(maxRho2,2)),...
            ' $c$=',num2str(round(c,2)),' $c_{11}^{SIR}$=',num2str(round(c11,2)),' $c_{12}^{SIR}$=',num2str(round(c12,2)),' $c_{21}$=',num2str(round(c21,2)),' $c_{22}$=',num2str(round(c22,2)),...
            ]}],...
            'Interpreter','latex')
xlabel('$\rho$',"fontweight","bold",'Interpreter','latex')
ylabel('$U(\rho)$',"fontweight","bold",'Interpreter','latex')




